#!/bin/sh
read in
case "$in" in
  *127.0.0.1*)
    echo "$1 $in" >> @WS@/helper.log
    echo '{"headers":{"Authorization":["Bearer helpertok"]}}'
    exit 0
    ;;
  *) echo '{}' ;;
esac

